// Extraer los datos provenientes de la respuesta interactiva de WhatsApp (Evolution API)
const body = $('Webhook').item.json.body;
const data = body.data || {};

// Capturar el ID del botón o de la lista seleccionada
const selectedButtonId = data.message?.buttonsResponseMessage?.selectedButtonId 
                      || data.message?.listResponseMessage?.singleSelectReply?.selectedRowId 
                      || "";

// Parsea los datos (asumiendo que el ID del botón es algo como "confirmar_cita|FECHA|TIPO")
const partes = selectedButtonId.split('|');
const fechaInicio = partes[1] || "";
const tipoTramite = partes[2] || "Trámite de Extranjería";

// Datos del remitente en WhatsApp
const remoteJid = data.key?.remoteJid || "";
const nombreCliente = data.pushName || "Cliente WhatsApp";

return {
  accion: "crear",
  nombre_cliente: nombreCliente,
  tipo_tramite: tipoTramite,
  fecha_inicio: fechaInicio,
  remoteJid: remoteJid
};

// Extraer la salida previa de forma segura
let rawOutput = $json.output ?? $json.text ?? $json.response ?? $json;
let parsedData = {};

// Si ya es un objeto, úsalo directamente
if (typeof rawOutput === 'object' && rawOutput !== null) {
  parsedData = rawOutput;
} else {
  // Convertir a string y limpiar caracteres extraños de formato o saltos de línea iniciales
  let cleanText = String(rawOutput).trim();

  // Quitar bloques markdown si los hubiera
  cleanText = cleanText.replace(/^```(?:json)?/gi, '').replace(/```$/g, '').trim();

  try {
    parsedData = JSON.parse(cleanText);
  } catch (error) {
    // Si falla el parseo directo, intentamos limpiar llaves escapadas o saltos de línea al inicio
    try {
      let fixedText = cleanText.replace(/^[^{]*/, '').replace(/[^}]*$/, '');
      parsedData = JSON.parse(fixedText);
    } catch (e2) {
      parsedData = { respuesta: cleanText };
    }
  }
}

// Asegurar que la respuesta sea estrictamente un texto plano y no otro objeto anidado
let textoRespuesta = parsedData.respuesta ?? rawOutput;
if (typeof textoRespuesta === 'object') {
  textoRespuesta = textoRespuesta.respuesta || JSON.stringify(textoRespuesta);
}

return {
  json: {
    respuesta: String(textoRespuesta).trim(),
    es_cita: Boolean(parsedData.es_cita),
    nombre_cliente: parsedData.nombre_cliente || "",
    tipo_tramite: parsedData.tipo_tramite || "Trámite General",
    fecha_inicio: parsedData.fecha_inicio || "",
    fecha_fin: parsedData.fecha_fin || ""
  }
};

